export type Route =
  | "CATALYST_CONTINUATION"
  | "LIQUIDITY_REVERSION"
  | "REGIME_TREND"
  | "MODEL_DIRECTIONAL"
  | "NO_TRADE";

export interface PublicStatus {
  mode: AgentMode;
  reconciled: boolean;
}

export interface PublicDecision {
  decision_id: string;
  decision_type: string;
  occurred_at: string;
  route: Route | null;
  symbol: string | null;

display.text:
export type AgentMode = "RUNNING" | "PAUSED" | "RISK_HALTED" | "KILLED";

export type Route =
  | "CATALYST_CONTINUATION"
  | "LIQUIDITY_REVERSION"
  | "REGIME_TREND"
  | "MODEL_DIRECTIONAL"
  | "NO_TRADE";

export interface PublicStatus {
  mode: AgentMode;
  reconciled: boolean;
}

export interface PublicDecision {
  decision_id: string;
  decision_type: string;
  occurred_at: string;
  route: Route | null;
  symbol: string | null;
  summary: string;
}

export interface PublicDecisionPage {
  records: PublicDecision[];
  next_cursor: string | null;
}

export interface PublicDecisionFilters {
  search: string;
  route: Route | "";
}

export interface PublicPortfolioPoint {
  captured_at: string;
  equity: string;
  cash: string;
  net_pnl: string;
  daily_return: string;
  competition_return: string;
  drawdown: string;
  position_count: number;
  max_trade_risk_rate: string;
  total_open_risk_rate: string;
  overnight_open_risk_rate: string;
  max_group_open_risk_rate: string;
}

export interface PublicChallengerStatus {
  deployed: boolean;
  loaded: boolean;
  authority: "SHADOW_ONLY" | "PAPER_LIVE" | null;
  run_id: string | null;
  created_at: string | null;
  candidate: string | null;
  feature_schema: string | null;
  decision_gate: number | null;
  horizon_bars: number | null;
  timeframe_minutes: number | null;
  symbol_count: number | null;
  selection_score: number | null;
  validation_return: number | null;
  validation_sharpe: number | null;
  positive_folds: number | null;
  folds: number | null;
  holdout_return: number | null;
  holdout_sharpe: number | null;
  holdout_max_drawdown: number | null;
  holdout_trades: number | null;
  numeric_shadow_gate_passed: boolean | null;
  promotion_eligible: boolean;
  model_sha256: string | null;
}

export interface PublicSnapshot {
  status: PublicStatus;
  decisions: PublicDecision[];
  routeDecisions: PublicDecision[];
  portfolio: PublicPortfolioPoint[];
  challenger: PublicChallengerStatus;
  receivedAt: Date;
}

const API_BASE_URL = process.env.NEXT_PUBLIC_API_BASE_URL ?? "";

async function getJson<T>(path: string, signal: AbortSignal): Promise<T> {
  const response = await fetch(`${API_BASE_URL}${path}`, {
    signal,
    headers: { Accept: "application/json" },
    cache: "no-store",
  });
  if (!response.ok) {
    throw new Error(`Public API returned ${response.status}`);
  }
  return (await response.json()) as T;
}

export async function fetchPublicSnapshot(signal: AbortSignal): Promise<PublicSnapshot> {
  const [status, decisions, routeDecisions, portfolio, challenger] = await Promise.all([
    getJson<PublicStatus>("/api/public/status", signal),
    getJson<PublicDecision[]>("/api/public/decisions?limit=50", signal),
    getJson<PublicDecision[]>("/api/public/routes?limit=100", signal),
    getJson<PublicPortfolioPoint[]>("/api/public/portfolio?limit=200", signal),
    getJson<PublicChallengerStatus>("/api/public/challenger", signal).catch(() => ({
      deployed: false,
      loaded: false,
      authority: null,
      run_id: null,
      created_at: null,
      candidate: null,
      feature_schema: null,
      decision_gate: null,
      horizon_bars: null,
      timeframe_minutes: null,
      symbol_count: null,
      selection_score: null,
      validation_return: null,
      validation_sharpe: null,
      positive_folds: null,
      folds: null,
      holdout_return: null,
      holdout_sharpe: null,
      holdout_max_drawdown: null,
      holdout_trades: null,
      numeric_shadow_gate_passed: null,
      promotion_eligible: false,
      model_sha256: null,
    })),
  ]);
  return { status, decisions, routeDecisions, portfolio, challenger, receivedAt: new Date() };
}

export async function fetchPublicDecisionPage(
  filters: PublicDecisionFilters,
  cursor: string | null,
  signal: AbortSignal,
): Promise<PublicDecisionPage> {
  const params = new URLSearchParams({ limit: "25" });
  if (cursor) params.set("cursor", cursor);
  if (filters.search.trim()) params.set("search", filters.search.trim());
  if (filters.route) params.set("route", filters.route);
  return getJson<PublicDecisionPage>(`/api/public/decision-pages?${params}`, signal);
}

from __future__ import annotations

import asyncio
import logging
from collections.abc import AsyncIterator
from contextlib import asynccontextmanager
from typing import Annotated, cast

from fastapi import Depends, FastAPI, HTTPException, Query, Request
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel, ConfigDict

from catalyst_router.challenger import PublicChallengerStatus
from catalyst_router.container import Container
from catalyst_router.domain import (
    AgentMode,
    PublicDecisionPage,
    PublicDecisionRecord,
    PublicPortfolioPoint,
    Route,
)
from catalyst_router.settings import Settings

logger = logging.getLogger(__name__)


class PublicStatus(BaseModel):
    model_config = ConfigDict(extra="forbid")

    mode: AgentMode
    reconciled: bool


def get_container(request: Request) -> Container:
    return cast(Container, request.app.state.container)


ContainerDependency = Annotated[Container, Depends(get_container)]


def create_app(container: Container | None = None) -> FastAPI:
    app_container = container or Container.build(Settings.from_env())

    @asynccontextmanager
    async def lifespan(_: FastAPI) -> AsyncIterator[None]:
        if (
            app_container.settings.runtime_role != "reporting"
            and app_container.settings.auto_reconcile
            and app_container.broker is not None
        ):
            try:
                await asyncio.to_thread(app_container.reconciliation_service().reconcile)
            except Exception:
                logger.exception("startup reconciliation failed; agent remains fenced")
        yield

    app = FastAPI(title="Catalyst Router", version="0.1.0", lifespan=lifespan)
    app.add_middleware(
        CORSMiddleware,
        allow_origins=list(app_container.settings.cors_origins),
        allow_methods=["GET"],
        allow_headers=["Accept"],
    )
    app.state.container = app_container

    @app.get("/health")
    def health() -> dict[str, str]:
        return {"status": "ok"}

    @app.get("/ready")
    def ready(container: ContainerDependency) -> dict[str, str]:
        if not container.store.get_agent_state().is_reconciled:
            raise HTTPException(status_code=503, detail="current execution epoch is unreconciled")
        return {"status": "ready"}

    @app.get("/api/public/status", response_model=PublicStatus)
    def public_status(container: ContainerDependency) -> PublicStatus:
        state = container.store.get_agent_state()
        return PublicStatus(
            mode=state.mode,
            reconciled=state.is_reconciled,
        )

    @app.get("/api/public/decisions", response_model=list[PublicDecisionRecord])
    def public_decisions(
        container: ContainerDependency,
        limit: Annotated[int, Query(ge=1, le=100)] = 50,
    ) -> list[PublicDecisionRecord]:
        return container.store.list_public_decisions(limit)

    @app.get("/api/public/portfolio", response_model=list[PublicPortfolioPoint])
    def public_portfolio(
        container: ContainerDependency,
        limit: Annotated[int, Query(ge=1, le=1000)] = 200,
    ) -> list[PublicPortfolioPoint]:
        return container.store.list_public_portfolio(limit)

    @app.get("/api/public/routes", response_model=list[PublicDecisionRecord])
    def public_routes(
        container: ContainerDependency,
        limit: Annotated[int, Query(ge=1, le=1000)] = 100,
    ) -> list[PublicDecisionRecord]:
        return container.store.list_public_routes(limit)

    @app.get("/api/public/decision-pages", response_model=PublicDecisionPage)
    def public_decision_pages(
        container: ContainerDependency,
        limit: Annotated[int, Query(ge=1, le=100)] = 25,
        cursor: str | None = None,
        search: Annotated[str | None, Query(max_length=100)] = None,
        route: Route | None = None,
        decision_type: Annotated[str | None, Query(max_length=100)] = None,
    ) -> PublicDecisionPage:
        try:
            return container.store.list_public_decision_page(
                limit=limit,
                cursor=cursor,
                search=search,
                route=route,
                decision_type=decision_type,
            )
        except ValueError as error:
            raise HTTPException(status_code=422, detail="invalid decision page cursor") from error

    @app.get("/api/public/challenger", response_model=PublicChallengerStatus)
    def public_challenger(container: ContainerDependency) -> PublicChallengerStatus:
        if container.challenger is None:
            return PublicChallengerStatus.not_deployed()
        return container.challenger.status

    @app.post("/api/operator/reconcile", include_in_schema=False)
    def operator_reconcile() -> None:
        raise HTTPException(status_code=404)

    return app


app = create_app()

