               {[
                 { label: "Per trade", value: Number(latestPortfolio?.max_trade_risk_rate ?? 0), limit: 0.01, unit: "rate" },
-                { label: "Open stop-risk", value: Number(latestPortfolio?.total_open_risk_rate ?? 0), limit: 0.04, unit: "rate" },
